using System.ComponentModel;
using System.Globalization;
using System.Text;
namespace Bai4_13;
public class BookModel { public string BookId{get;set;}=""; public string Title{get;set;}=""; public string Author{get;set;}=""; public int Quantity{get;set;} public decimal UnitPrice{get;set;} public string CoverPath{get;set;}=""; public decimal TotalValue=>Quantity*UnitPrice; }
public class Form1:Form
{
 BindingList<BookModel> books=new(); BindingSource bs=new(); TextBox id=new(),title=new(),author=new(),qty=new(),price=new(); PictureBox cover=new(); DataGridView grid=new(); ToolStripStatusLabel count,value,time; string coverPath="";
 public Form1(){Text="Bài 4.13 - Book Manager";Width=1200;Height=750;MinimumSize=new Size(900,550);var menu=new MenuStrip();var file=new ToolStripMenuItem("File");var open=new ToolStripMenuItem("Mở file CSV");var save=new ToolStripMenuItem("Lưu file CSV");var exit=new ToolStripMenuItem("Thoát");open.Click+=(_,_)=>ImportCsv();save.Click+=(_,_)=>ExportCsv();exit.Click+=(_,_)=>Close();file.DropDownItems.AddRange(new ToolStripItem[]{open,save,new ToolStripSeparator(),exit});var edit=new ToolStripMenuItem("Edit");var addM=new ToolStripMenuItem("Thêm");var delM=new ToolStripMenuItem("Xóa");addM.Click+=(_,_)=>AddBook();delM.Click+=(_,_)=>DeleteBook();edit.DropDownItems.AddRange(new ToolStripItem[]{addM,delM});menu.Items.AddRange(new ToolStripItem[]{file,edit});MainMenuStrip=menu;Controls.Add(menu);
 var tools=new ToolStrip{Dock=DockStyle.Top};var op=new ToolStripButton("Mở file");var sv=new ToolStripButton("Lưu file");var ad=new ToolStripButton("Thêm mới");op.Click+=(_,_)=>ImportCsv();sv.Click+=(_,_)=>ExportCsv();ad.Click+=(_,_)=>AddBook();tools.Items.AddRange(new ToolStripItem[]{op,sv,ad});Controls.Add(tools);tools.BringToFront();menu.BringToFront();
 var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(8),ColumnCount=2,RowCount=1};root.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,330));root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));Controls.Add(root);root.BringToFront();
 var left=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};root.Controls.Add(left,0,0);Field("Mã sách",id,left);Field("Tên sách",title,left);Field("Tác giả",author,left);Field("Số lượng",qty,left);Field("Đơn giá",price,left);cover.Size=new Size(220,160);cover.SizeMode=PictureBoxSizeMode.Zoom;cover.BorderStyle=BorderStyle.FixedSingle;left.Controls.Add(cover);var pick=new Button{Text="Tải ảnh bìa"};pick.Click+=(_,_)=>PickCover();left.Controls.Add(pick);var bAdd=new Button{Text="Thêm mới"};var bEdit=new Button{Text="Sửa"};var bDel=new Button{Text="Xóa"};left.Controls.AddRange(new Control[]{bAdd,bEdit,bDel});bAdd.Click+=(_,_)=>AddBook();bEdit.Click+=(_,_)=>EditBook();bDel.Click+=(_,_)=>DeleteBook();
 grid.Dock=DockStyle.Fill;grid.AutoGenerateColumns=false;grid.ReadOnly=true;grid.AllowUserToAddRows=false;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;root.Controls.Add(grid,1,0);Col("Mã sách","BookId",80);Col("Tên sách","Title",180);Col("Tác giả","Author",140);Col("SL","Quantity",60);Col("Đơn giá","UnitPrice",100,"N0");Col("Giá trị","TotalValue",110,"N0");Col("Ảnh","CoverPath",140);bs.DataSource=books;grid.DataSource=bs;grid.SelectionChanged+=(_,_)=>LoadRow();
 var status=new StatusStrip();count=new ToolStripStatusLabel();value=new ToolStripStatusLabel();time=new ToolStripStatusLabel();status.Items.AddRange(new ToolStripItem[]{count,new ToolStripStatusLabel(" | "),value,new ToolStripStatusLabel{Spring=true},time});Controls.Add(status);status.BringToFront();var timer=new System.Windows.Forms.Timer{Interval=1000};timer.Tick+=(_,_)=>time.Text=DateTime.Now.ToString("HH:mm:ss");timer.Start();FormClosed+=(_,_)=>timer.Dispose();books.ListChanged+=(_,_)=>UpdateStatus();books.Add(new(){BookId="S001",Title="Lập trình C#",Author="Nguyễn Văn A",Quantity=5,UnitPrice=120000});books.Add(new(){BookId="S002",Title="Cơ sở dữ liệu",Author="Trần Văn B",Quantity=3,UnitPrice=95000});UpdateStatus();}
 void Field(string label,TextBox box,FlowLayoutPanel p){p.Controls.Add(new Label{Text=label,Width=260});box.Width=260;p.Controls.Add(box);}
 void Col(string h,string prop,int w,string fmt=null)=>grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText=h,DataPropertyName=prop,Width=w,DefaultCellStyle=new DataGridViewCellStyle{Format=fmt??""}});
 void PickCover(){using var d=new OpenFileDialog{Filter="Ảnh (*.png;*.jpg;*.jpeg)|*.png;*.jpg;*.jpeg"};if(d.ShowDialog()==DialogResult.OK){try{using var im=Image.FromFile(d.FileName);cover.Image?.Dispose();cover.Image=new Bitmap(im);coverPath=d.FileName;}catch(Exception ex){MessageBox.Show(ex.Message);}}}
 BookModel Read(){if(string.IsNullOrWhiteSpace(id.Text)||string.IsNullOrWhiteSpace(title.Text)||string.IsNullOrWhiteSpace(author.Text)||!int.TryParse(qty.Text,out int q)||q<0||!decimal.TryParse(price.Text,NumberStyles.Number,CultureInfo.CurrentCulture,out decimal p)||p<0){MessageBox.Show("Nhập đủ thông tin; số lượng và giá không âm.");return null;}return new(){BookId=id.Text.Trim(),Title=title.Text.Trim(),Author=author.Text.Trim(),Quantity=q,UnitPrice=p,CoverPath=coverPath};}
 void AddBook(){var b=Read();if(b==null)return;if(books.Any(x=>x.BookId==b.BookId)){MessageBox.Show("Mã sách đã tồn tại.");return;}books.Add(b);}
 void EditBook(){if(grid.CurrentRow?.DataBoundItem is not BookModel old)return;var b=Read();if(b==null)return;old.BookId=b.BookId;old.Title=b.Title;old.Author=b.Author;old.Quantity=b.Quantity;old.UnitPrice=b.UnitPrice;old.CoverPath=b.CoverPath;bs.ResetBindings(false);}
 void DeleteBook(){if(grid.CurrentRow?.DataBoundItem is BookModel b&&MessageBox.Show("Xóa sách?","Xác nhận",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)==DialogResult.Yes)books.Remove(b);}
 void LoadRow(){if(grid.CurrentRow?.DataBoundItem is not BookModel b)return;id.Text=b.BookId;title.Text=b.Title;author.Text=b.Author;qty.Text=b.Quantity.ToString();price.Text=b.UnitPrice.ToString(CultureInfo.CurrentCulture);coverPath=b.CoverPath;cover.Image?.Dispose();cover.Image=null;if(File.Exists(coverPath)){try{using var im=Image.FromFile(coverPath);cover.Image=new Bitmap(im);}catch{}}}
 void UpdateStatus(){count.Text="Tổng số đầu sách: "+books.Count;value.Text="Tổng giá trị kho: "+books.Sum(x=>x.TotalValue).ToString("N0")+" đ";}
 void ExportCsv(){using var d=new SaveFileDialog{Filter="CSV (*.csv)|*.csv",FileName="Books.csv"};if(d.ShowDialog()!=DialogResult.OK)return;try{using var w=new StreamWriter(d.FileName,false,new UTF8Encoding(true));w.WriteLine("BookId,Title,Author,Quantity,UnitPrice,CoverPath");foreach(var b in books)w.WriteLine(string.Join(",",new[]{b.BookId,b.Title,b.Author,b.Quantity.ToString(),b.UnitPrice.ToString(CultureInfo.InvariantCulture),b.CoverPath}.Select(Escape)));MessageBox.Show("Đã xuất CSV.");}catch(Exception ex){MessageBox.Show(ex.Message);}}
 void ImportCsv(){using var d=new OpenFileDialog{Filter="CSV (*.csv)|*.csv"};if(d.ShowDialog()!=DialogResult.OK)return;try{var list=new List<BookModel>();foreach(var line in File.ReadLines(d.FileName).Skip(1)){var f=Parse(line);if(f.Count>=6&&int.TryParse(f[3],out int q)&&decimal.TryParse(f[4],NumberStyles.Number,CultureInfo.InvariantCulture,out decimal p))list.Add(new(){BookId=f[0],Title=f[1],Author=f[2],Quantity=q,UnitPrice=p,CoverPath=f[5]});}books.Clear();foreach(var b in list)books.Add(b);MessageBox.Show("Đã nhập "+list.Count+" đầu sách.");}catch(Exception ex){MessageBox.Show(ex.Message);}}
 string Escape(string s)=>"\""+(s??"").Replace("\"","\"\"")+"\"";
 List<string> Parse(string line){var a=new List<string>();var b=new StringBuilder();bool q=false;for(int i=0;i<line.Length;i++){char c=line[i];if(c=='"'){if(q&&i+1<line.Length&&line[i+1]=='"'){b.Append('"');i++;}else q=!q;}else if(c==','&&!q){a.Add(b.ToString());b.Clear();}else b.Append(c);}a.Add(b.ToString());return a;}
}
